// Pega os dados vindos do template do Totem
let dadosPedido = msg.payload;
let nomeString = dadosPedido.nome || "";

// Garante que a string tenha um tamanho fixo de 16 caracteres completando com espaços
nomeString = nomeString.padEnd(16, " "); 

let modbusRegisters = [];
// Converte os caracteres em registradores de 16 bits (2 caracteres por registrador)
for (let i = 0; i < nomeString.length; i += 2) {
    let byte1 = nomeString.charCodeAt(i);
    let byte2 = nomeString.charCodeAt(i + 1) || 32; // 32 = Espaço vazio
    // Combina os dois bytes em uma word (16-bits)
    modbusRegisters.push((byte1 << 8) | byte2); 
}

// Mensagem 1: Envia o Nome (Array de inteiros) para os Holding Registers (ex: 40001 a 40008)
let msgRegistradores = {
    payload: modbusRegisters,
    fc: 16 // Function code para Write Multiple Registers
};

// Mensagem 2: Envia o pulso de 'novoPedido' (Boolean) para um Coil (ex: 00001)
let msgTrigger = {
    payload: dadosPedido.novoPedido, 
    fc: 5 // Function code para Write Single Coil
};

// Envia para as duas saídas do nó (crie 2 saídas na configuração deste nó Function)
return [msgRegistradores, msgTrigger];

// Armazena ou recupera os blocos na memória de fluxo do Node-RED
let bloco1 = flow.get('bloco1') || [];
let bloco2 = flow.get('bloco2') || [];

// Atualiza o bloco correspondente com base no tópico da mensagem recebida
if (msg.topic === 'bloco1') {
    bloco1 = msg.payload;
    flow.set('bloco1', bloco1);
} else if (msg.topic === 'bloco2') {
    bloco2 = msg.payload;
    flow.set('bloco2', bloco2);
}

// Une os dois arrays de registradores em um array contínuo de 225 WORDS
let rawRegisters = bloco1.concat(bloco2);

// Só executa o parser se já tiver recebido dados de ambos os blocos
if (rawRegisters.length < 225) {
    return null; 
}

const MAPA_ESTADOS = {
    1: 'Em espera na fila (Estoque 1 - Bruto)',
    2: 'Torno: Torneando o primeiro lado',
    3: 'Torno: Torneando o segundo lado',
    4: 'Estoque 2 (Torneadas): Aguardando Centro de Usinagem',
    5: 'Centro: Usinando peça',
    6: 'Estoque 3 (Usinadas): Aguardando Centro para customizar a sua peça!',
    7: 'Centro: Customizando sua peça',
    8: 'Peça pronta'
};

let pedidosFormatados = [];
const totalPedidos = Math.floor(rawRegisters.length / 9);

for (let i = 0; i < totalPedidos; i++) {
    let offset = i * 9;

    // Pega o código de estado na 9ª WORD
    let estadoCodigo = rawRegisters[offset + 8] & 0xFF;

    // Pula slots desativados
    if (estadoCodigo === 0) continue;

    // Decodifica a String do Nome
    let nomeChars = [];
    for (let w = 0; w < 8; w++) {
        let wordVal = rawRegisters[offset + w];
        let charHigh = (wordVal >> 8) & 0xFF;
        let charLow = wordVal & 0xFF;

        if (charHigh !== 0) nomeChars.push(String.fromCharCode(charHigh));
        if (charLow !== 0) nomeChars.push(String.fromCharCode(charLow));
    }

    let nomeString = nomeChars.join("").trim();

    if (nomeString.length > 0) {
        pedidosFormatados.push({
            nome: nomeString,
            tipo: nomeString === 'SENAI' ? 'PADRAO' : 'PERSONALIZADO',
            estado: MAPA_ESTADOS[estadoCodigo] || 'Em processamento',
            timestamp: new Date().toLocaleTimeString()
        });
    }
}

// Adiciona um ID único baseado na posição da fila/registrador Modbus
msg.payload = msg.payload.map((item, index) => ({
    id: `ordem_${index + 1}_${item.nome}`,
    ...item
}));

return { payload: pedidosFormatados };

// Avalia a entrada booleana (true = operando, false = parado)
const operando = msg.payload[0] || msg.payload[1] === true;

// Retorna unicamente a mensagem necessária para o sinótico
return {
    topic: "simulacao_centro",
    payload: {
        estacao: "centro",
        operando: operando
    }
};

